class Solution {
    public String restoreString(String s, int[] indices) {
        char[] answer = new char[s.length()];
        for (int i = 0; i < s.length(); i++) {
            answer[indices[i]] = s.charAt(i);
        }
        return new String(answer);
    }
}

class Solution {
    public String restoreString(String s, int[] indices) {
        int n = s.length();
        int[] source = new int[n];
        for (int i = 0; i < n; i++) {
            source[indices[i]] = i;
        }

        StringBuilder answer = new StringBuilder(n);
        for (int target = 0; target < n; target++) {
            answer.append(s.charAt(source[target]));
        }
        return answer.toString();
    }
}

import java.util.Arrays;

class Solution {
    public String restoreString(String s, int[] indices) {
        int n = s.length();
        int[][] pairs = new int[n][2];
        for (int i = 0; i < n; i++) {
            pairs[i][0] = indices[i];
            pairs[i][1] = s.charAt(i);
        }

        Arrays.sort(pairs, (a, b) -> Integer.compare(a[0], b[0]));
        StringBuilder answer = new StringBuilder(n);
        for (int[] pair : pairs) {
            answer.append((char) pair[1]);
        }
        return answer.toString();
    }
}

class Solution {
    public String restoreString(String s, int[] indices) {
        char[] letters = s.toCharArray();
        int[] destinations = indices.clone();

        for (int i = 0; i < letters.length; i++) {
            while (destinations[i] != i) {
                int target = destinations[i];

                char tempLetter = letters[i];
                letters[i] = letters[target];
                letters[target] = tempLetter;

                int tempDestination = destinations[i];
                destinations[i] = destinations[target];
                destinations[target] = tempDestination;
            }
        }
        return new String(letters);
    }
}
